def f(g):
    A=[r[:] for r in g]; h,w=len(A),len(A[0])
    from collections import Counter
    cnt=Counter(x for r in A for x in r)
    # find rectangle outlines: color c forming a closed box
    out=[r[:] for r in A]
    rects={}
    for c in set(cnt)-{0}:
        pts=[(i,j) for i in range(h) for j in range(w) if A[i][j]==c]
        if len(pts)<4: continue
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # verify it's a full outline
        exp={(i,j) for i in (r0,r1) for j in range(c0,c1+1)} | {(i,j) for j in (c0,c1) for i in range(r0,r1+1)}
        if set(pts)==exp and r1-r0>=1 and c1-c0>=1 and len(pts)>=8:
            rects[c]=(r0,r1,c0,c1)
    # scatter colors = colors not in rects and not 0
    for c,n in cnt.items():
        if c==0 or c in rects: continue
        # find rect whose even interior count == n (and fits)
        cand=[rc for rc,(r0,r1,c0,c1) in rects.items()
              if sum(1 for i in range(r0+1,r1) for j in range(c0+1,c1) if (i+j)%2==0)==n]
        # if multiple, assign largest rect to largest remaining count
        if not cand: continue
        if len(cand)>1:
            cand.sort(key=lambda rc: rects[rc], reverse=False)
        rc=cand[0]; r0,r1,c0,c1=rects.pop(rc)
        k=0
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                if (i+j)%2==0 and k<n:
                    out[i][j]=c; k+=1
    return out

